(function(root){
'use strict';
const V=root.GuildValues||(typeof require==='function'?require('./values.js'):null);
const names=['Critical Failure','Failure','Success','Critical Success'];
const phases=['Insertion','Engagement','Extraction'];
const templates=[
 {key:'escort',name:'Escort Through Dock Nine',kind:'standard',client:'Helix Transit',skills:['Piloting','Athletics','Survival'],description:'A convoy needs safe passage through a contested orbital freight lane. Keep the crew moving when the route gets ugly.'},
 {key:'relay',name:'Restore the Ghost Relay',kind:'standard',client:'Station Authority',skills:['Stealth','Computers','Piloting'],essential:1,description:'Slip into a silent relay platform and restore the uplink before the station loses its long-range comms. Engagement is Essential: the relay must actually come online.'},
 {key:'cargo',name:'Cold Cargo, Clear Route',kind:'routine',client:'Helix Transit',skills:['Piloting','Computers','Survival'],description:'Move a sealed medical shipment between two nearby docks. A reliable route, with a tight client budget.'},
 {key:'breach',name:'Breach the Derelict',kind:'demanding',client:'Salvage Cooperative',skills:['Piloting','Athletics','Survival'],description:'Board a tumbling wreck, secure its dangerous cargo, and clear the debris field. Every phase must succeed; the crew needs a month to recover afterwards.'},
 {key:'exclusive',name:'Last Window at Meridian',kind:'exclusive',client:'Station Authority',skills:['Stealth','Computers','Piloting'],description:'A client has one opening to retrieve sensitive navigation data. Every phase must succeed. Accept only if you can deploy now and complete next turn; one recovery turn follows.'}
];
const people=[
 {name:'Vex',role:'Scout & navigator',color:'teal',bio:'Patient on approach. Knows when an exit is about to close.',skills:{Stealth:'high',Survival:'high',Piloting:'moderate',Athletics:'moderate'}},
 {name:'Briggs',role:'Breach specialist',color:'amber',bio:'Keeps the line steady when the operation gets loud.',skills:{Athletics:'high',Medicine:'high',Survival:'moderate',Piloting:'moderate'}},
 {name:'Patch',role:'Systems specialist',color:'violet',bio:'Can coax a locked terminal back to life. Less comfortable in open terrain.',skills:{Computers:'high',Crafting:'high',Piloting:'moderate',Society:'moderate'}},
 {name:'Halo',role:'Pilot & negotiator',color:'blue',bio:'Makes difficult arrivals look routine, and knows who to call afterward.',skills:{Piloting:'high',Diplomacy:'high',Stealth:'moderate',Medicine:'moderate'}},
 {name:'Echo',role:'Signals & field support',color:'violet',bio:'Tracks strange signals and keeps the team oriented.',skills:{Computers:'high',Survival:'high',Stealth:'moderate',Society:'moderate'}},
 {name:'Kestrel',role:'Recon & technical entry',color:'teal',bio:'Prefers a quiet insertion and a clear contingency plan.',skills:{Stealth:'high',Crafting:'high',Computers:'moderate',Piloting:'moderate'}}
];
const leaderFeats=[
 {id:'breach',name:'Breach Commander',text:'+1 Engagement with Athletics.'},
 {id:'ghost',name:'Ghost Route',text:'+1 Insertion with Stealth.'},
 {id:'hardcase',name:'Hardcase',text:'Reduce phase-added squad recovery by 1; keep mandatory recovery.'},
 {id:'systems',name:'Systems Tactician',text:'+1 Engagement with Computers.'},
 {id:'navigator',name:'Field Navigator',text:'+1 Extraction with Survival.'},
 {id:'advocate',name:'Crew Advocate',text:'+1 participating crew Loyalty on completion.'}
];
const guildFeats=[
 {id:'trusted',level:2,name:'Trusted Client',text:'Optionally secure one ordinary Standard job from a known contact free each turn.'},
 {id:'pipeline',level:2,name:'Recruitment Pipeline',text:'First recruitment search each turn yields one extra candidate, maximum three.'},
 {id:'cadre',level:4,name:'Training Cadre',text:'Reduce trainer cost by 25 per cohort and block.'},
 {id:'provisioned',level:4,name:'Well Provisioned',text:'Raise relevant automatic support cap from +3 to +4.'},
 {id:'standing',level:6,requires:'trusted',name:'Standing Agreement',text:'A known contact supplies one optional, freely secured Standard offer each turn. Replaces Trusted Client.'}
];
function clamp(x,a,b){return Math.max(a,Math.min(b,x));}
function round(x){return Math.floor(x+.5);}
function wage(l){return 5*round(50*1.25**(l-1)/5);}
function rank(l){return l>=17?'Legendary':l>=9?'Master':l>=5?'Expert':'Trained';}
function support(m,skill){return m.skills[skill]?V.support_by_rank[rank(m.level).toLowerCase()]:0;}
function skill(m,k){return m.skills[k]?V['skill_'+m.skills[k]][m.level]:2;}
function degree(face,mod,dc){let d=face+mod-dc;let n=d>=10?3:d>=0?2:d<=-10?0:1;return clamp(n+(face===20?1:face===1?-1:0),0,3);}
function die(seed,...keys){let h=2166136261;for(const c of JSON.stringify([seed,...keys])){h=Math.imul(h^c.charCodeAt(0),16777619);}h^=h>>>16;h=Math.imul(h,2246822507);h^=h>>>13;h=Math.imul(h,3266489909);h^=h>>>16;return (h>>>0)%20+1;}
function id(s,prefix){return prefix+(++s.serial);}
function log(s,title,text,kind='note'){s.log.unshift({turn:s.turn,title,text,kind});}
function money(s,amount,note,category){s.cash+=amount;s.ledger.push({turn:s.turn,amount,note,category});}
function error(text){throw new Error(text);}
function available(m){return m.status==='Available';}
function merc(s,mid){let m=s.mercs.find(x=>x.id===mid);if(!m)error('That operative is not in the roster.');return m;}
function offer(s,cid){let c=s.board.find(x=>x.id===cid);if(!c)error('That contract is no longer on the board.');return c;}
function officer(s,oid){let o=s.officers.find(x=>x.id===oid);if(!o)error('Choose an officer.');return o;}
function administrativeDC(s){return V.level_dc[Math.min(20,2*s.guildLevel-1)];}
function checkFunds(s,cost){if(s.cash<cost)error('The treasury cannot fund that cost.');}
function checkAction(s,oid,cost=1){if(s.phase!=='activity')error('Finish Upkeep or the current event before taking Guild Actions.');const o=officer(s,oid);if(s.actions<cost)error('No shared Guild Actions remain.');if(cost&&o.used+cost>2)error('That officer has already used their two actions.');return o;}
function spend(s,oid,label,cost=1,cashCost=0){const o=checkAction(s,oid,cost);checkFunds(s,cashCost);s.actions-=cost;o.used+=cost;if(cashCost)money(s,-cashCost,label,'management');s.actionHistory.push({turn:s.turn,officer:o.name,action:label,cost,credits:cashCost});}
function checkTrained(o,k){if(!o.skills[k])error('This officer needs Trained '+k+'.');}
function rollAdmin(s,oid,label,k='Diplomacy',dc=administrativeDC(s)){const o=officer(s,oid);let face=die(s.seed,'admin',s.turn,s.actionHistory.length,label);let mod=o.skills[k]||2;let d=degree(face,mod,dc);s.lastRoll={label,face,modifier:mod,dc,degree:d};log(s,label,`${o.name}: d20 ${face} +${mod} vs DC${dc}: ${names[d]}.`,'roll');return d;}
function xp(s,m,amount){m.xp+=amount;while(m.level<20&&m.xp>=1000){m.xp-=1000;m.level++;log(s,m.name+' reaches Level '+m.level,'Skill benchmarks and future wages increase. In-progress wage quotes stay fixed.','good');}}
function changeRep(s,n){s.reputation=clamp(s.reputation+n,-20,100);}
function changeLoyalty(s,m,n){m.loyalty=clamp(m.loyalty+n,0,100);if(m.loyalty===0&&!m.leaveAt){m.leaveAt=s.turn+1;log(s,m.name+' gives notice','They will become Inactive next boundary unless Loyalty is raised before then.','bad');}}
function makeMerc(s,template,level=1){return {id:id(s,'m'),...JSON.parse(JSON.stringify(template)),level,xp:0,loyalty:50,status:'Available',leaderFeat:null};}
function addOffer(s,key,level=1,extra={}){let t=templates.find(x=>x.key===key);let c={...JSON.parse(JSON.stringify(t)),id:id(s,'c'),level,status:'Offer',expires:s.turn+1,...extra};s.board.push(c);return c;}
function fresh(seed=7,free=false){let s={schema:'contract-operations-browser-1',rules:'0.3.1',seed:Number.isInteger(Number(seed))?Number(seed):7,freeAcquisition:!!free,turn:1,phase:'activity',serial:0,cash:2000,actions:3,guildLevel:1,guildXP:0,pendingGuildXP:0,featChoices:0,guildFeats:[],contacts:['Helix Transit','Station Authority'],reputation:0,relations:2,mercs:[],board:[],jobs:[],cohorts:[],projects:[],facilities:[],arrears:[],actionHistory:[],ledger:[],log:[],feedback:'',metrics:{completed:0,failed:0,trainingBlocks:0,hires:0},trustedUsed:false,pipelineUsed:false,searches:0,upkeep:null,event:null,lastRoll:null};s.officers=[{id:'command',name:'Commander Rook',role:'Commander · Contract Broker',used:0,skills:{Diplomacy:10,Performance:10,Piloting:10,Survival:10}},{id:'quarter',name:'Quartermaster Nyx',role:'Quartermaster · Personnel Officer',used:0,skills:{Diplomacy:10,Computers:10,Crafting:10,Medicine:10,Society:10}}];for(let i=0;i<4;i++)s.mercs.push(makeMerc(s,people[i]));addOffer(s,'escort');addOffer(s,'relay');log(s,'Open for business','Four operatives. Two PC officers. Two clients. Three shared actions. There is no preceding-month bill at setup.','good');return s;}
function quote(s,c,ids,leads,leader=null){if(ids.length<2||ids.length>6)error('This card requires between two and six operatives.');if(new Set(ids).size!==ids.length)error('An operative cannot occupy two squad slots.');let squad=ids.map(i=>merc(s,i));if(squad.some(m=>!available(m)||m.dispatchedTurn===s.turn))error('Every selected operative must be Available and not already assigned a new job this turn.');let average=Math.floor(squad.reduce((a,m)=>a+m.level,0)/ids.length);let minimum=Math.max(1,c.level-2);if(average<minimum)error(`This card needs minimum Squad Level ${minimum}; this squad averages ${average}.`);if(leads.length!==3||leads.some(l=>!ids.includes(l)))error('Declare one squad member as each phase lead.');if(leader){const l=merc(s,leader);if(!ids.includes(leader)||l.level<5||!l.leaderFeat)error('Choose a Level 5+ squad member with a chosen Leader Feat.');}let modifier=clamp(1-.1*Math.max(0,ids.length-4)-.1*Math.max(0,average-c.level),.5,1);let card=V.contracts[c.kind];let payout=round(3*4*wage(c.level)*card.payout_factor*modifier);let pay=squad.reduce((a,m)=>a+wage(m.level),0);let dc=V.level_dc[c.level]+card.dc_offset+clamp(4-ids.length,-2,2);const cap=s.guildFeats.includes('provisioned')?4:3;let prepared=c.preparation&&c.preparation.expires>=s.turn?c.preparation:null;let leaderFeat=leader?merc(s,leader).leaderFeat:null;let checks=c.skills.map((k,p)=>{let lead=merc(s,leads[p]);let helpers=squad.filter(m=>m.id!==lead.id&&m.skills[k]);let raw=helpers.reduce((a,m)=>a+support(m,k),0);let b=Math.min(cap,raw);let feat=(leaderFeat==='breach'&&p===1&&k==='Athletics')||(leaderFeat==='ghost'&&p===0&&k==='Stealth')||(leaderFeat==='systems'&&p===1&&k==='Computers')||(leaderFeat==='navigator'&&p===2&&k==='Survival')?1:0;let prep=prepared&&prepared.phase===p?prepared.bonus:0;let circumstance=Math.max(0,feat,prep)+Math.min(0,prep);return {phase:phases[p],skill:k,lead:lead.id,leadName:lead.name,skillBonus:skill(lead,k),support:b,supporters:helpers.map(m=>({id:m.id,name:m.name,rank:rank(m.level),contribution:support(m,k),marginal:Math.min(cap,raw)-Math.min(cap,raw-support(m,k))})),circumstance,modifier:skill(lead,k)+b+circumstance,dc};});return {squadLevel:average,minimum,modifier,payout,pay,checks,leaderFeat,wageQuotes:squad.map(m=>({id:m.id,name:m.name,level:m.level,wage:wage(m.level)}))};}
function secure(s,cid,oid,useFeat=false){const c=offer(s,cid);if(c.status!=='Offer'||c.expires<s.turn)error('That offer has expired or is already accepted.');let waiver=useFeat&&c.kind==='standard'&&s.contacts.includes(c.client)&&!s.trustedUsed&&(s.guildFeats.includes('trusted')||s.guildFeats.includes('standing'));if(useFeat&&!waiver&&!c.standing)error('No eligible acquisition waiver is available for this card.');let cost=s.freeAcquisition||waiver||c.standing?0:1;spend(s,oid,'Secure Contract: '+c.name,cost);if(waiver||c.standing)s.trustedUsed=true;c.status='Accepted';c.acceptedTurn=s.turn;c.deployBy=c.kind==='exclusive'?s.turn:s.turn+1;log(s,'Contract secured',`${c.name}. ${cost?'One Guild Action spent.':'Acquisition is free.'} Deployment is routine; it still requires Available crew.`,'good');}
function deploy(s,cid,ids,leads,leader=null){if(s.phase!=='activity')error('Deploy during Activity.');let c=offer(s,cid);if(c.status!=='Accepted')error('Secure this contract before deploying.');if(c.deployBy<s.turn)error('Its deployment window has closed.');let q=quote(s,c,ids,leads,leader);let j={id:id(s,'j'),contract:JSON.parse(JSON.stringify(c)),departure:s.turn,due:s.turn+1,ids:[...ids],leads:[...leads],leader,quote:q,rolls:[],settled:false};s.jobs.push(j);c.status='Deployed';ids.forEach(i=>{const m=merc(s,i);m.status='Deployed';m.dispatchedTurn=s.turn;});log(s,'Squad deployed',`${c.name}; Squad Level ${q.squadLevel}. Frozen wages ${q.pay}; client payout ${q.payout} only on completion. No deployment action.`,'good');return j;}
function network(s,oid,mode='recruits',level=1){level=Number(level);if(!Number.isInteger(level)||level<1||level>Math.min(20,2*s.guildLevel+1))error('Choose a search level available to this guild.');if(!['recruits','contracts'].includes(mode))error('Choose a network search mode.');spend(s,oid,'Work the Network: '+mode);let d=rollAdmin(s,oid,'Network '+mode,'Diplomacy',V.level_dc[level]);let count=d;if(mode==='recruits'&&s.guildFeats.includes('pipeline')&&!s.pipelineUsed){count=Math.min(3,count+1);s.pipelineUsed=true;}s.searches++;for(let n=0;n<count;n++){if(mode==='recruits'){let index=(die(s.seed,'candidate',s.turn,s.searches,n)-1)%people.length;let m=makeMerc(s,people[index],level);m.name+=' '+s.serial;m.status='Candidate';m.expires=s.turn+1;s.mercs.push(m);}else{let key=templates[(die(s.seed,'lead',s.turn,s.searches,n)-1)%4].key;addOffer(s,key,level);}}log(s,'Network results',`${count} ${mode==='recruits'?'candidates':'leads'} found at Level ${level}; available until the end of Guild Turn ${s.turn+1}. Finding is separate from hiring or securing.`,'good');return count;}
function hire(s,mid,oid){let m=merc(s,mid);if(m.status!=='Candidate'||m.expires<s.turn)error('That candidate is no longer available.');const cost=2*wage(m.level);spend(s,oid,'Recruit Operative: '+m.name,1,cost);m.status='Onboarding';m.readyAt=s.turn+1;s.metrics.hires++;log(s,'Recruit onboarding',`${m.name} joins next Guild Turn. Hiring cost ${cost}; future assignment wage ${wage(m.level)}. No same-turn deployment or training.`,'good');}
function trainingCost(s,ids){return 50-(s.guildFeats.includes('cadre')?25:0)+25*ids.length;}
function trainingCapacity(s){return s.facilities.some(f=>f.type==='training_suite'&&f.condition==='Operational')?6:4;}
function train(s,ids,oid){if(!ids.length||ids.length>trainingCapacity(s)||new Set(ids).size!==ids.length)error('Select one to '+trainingCapacity(s)+' unique trainees.');let members=ids.map(i=>merc(s,i));if(members.some(m=>!available(m)))error('Training requires Available staff.');let cost=trainingCost(s,ids);spend(s,oid,'Run Training Drills',1,cost);let c={id:id(s,'t'),ids:[...ids],block:1,due:s.turn+1,active:true};s.cohorts.push(c);members.forEach(m=>m.status='Training');log(s,'Training begins',`${ids.length} operatives commit for 30 days. Cost ${cost}; 150 XP each at next Upkeep. Routine trainer included; the officer remains available.`,'good');}
function promote(s,oid){spend(s,oid,'Promote the Guild',1,50);let d=rollAdmin(s,oid,'Promote the Guild');let n=V.promotion_reputation_by_degree[d];changeRep(s,n);log(s,'Public reputation',`${n>=0?'+':''}${n} Reputation. ${names[d]}.` ,n<0?'bad':'good');}
function morale(s,ids,oid){if(!ids.length||new Set(ids).size!==ids.length)error('Select personnel to include.');let members=ids.map(i=>merc(s,i));if(members.some(m=>!['Available','Recovering'].includes(m.status)))error('This local program can reach Available or Recovering crew.');spend(s,oid,'Boost Morale',1,10*ids.length);let d=rollAdmin(s,oid,'Boost Morale');let n=V.morale_loyalty_by_degree[d];members.forEach(m=>changeLoyalty(s,m,n));log(s,'Crew recognition',`${names[d]}: ${n>=0?'+':''}${n} Loyalty for ${ids.length} staff. Reputation is separate.`,n<0?'bad':'good');}
function recon(s,cid,oid,p=1){const c=offer(s,cid);if(c.status!=='Accepted')error('Recon prepares an accepted, undeployed contract.');if(c.preparation)error('This job already has a recorded recon attempt; no free repeat on unchanged facts.');let o=checkAction(s,oid);checkTrained(o,'Computers');if(!Number.isInteger(p)||p<0||p>2)error('Choose a phase.');spend(s,oid,'Conduct Digital Recon');let d=rollAdmin(s,oid,'Digital Recon','Computers');let bonus=[-1,0,1,2][d];c.preparation={phase:p,bonus,expires:s.turn+1};log(s,'Recon briefing',`${phases[p]} on ${c.name}: ${bonus>=0?'+':''}${bonus}. Applies once; highest circumstance bonus only. No mission roll added.`,bonus<0?'bad':'good');}
function broker(s,oid,level=1){if(s.reputation<20)error('Exclusive brokerage requires Friendly Reputation (20).');level=Number(level);if(!Number.isInteger(level)||level<1||level>Math.min(20,2*s.guildLevel+1))error('Choose an available target level.');let o=checkAction(s,oid);checkTrained(o,'Diplomacy');spend(s,oid,'Broker Exclusive Deal',1,50);let d=rollAdmin(s,oid,'Exclusive brokerage','Diplomacy');let count=d>=2?d-1:0;for(let i=0;i<count;i++)addOffer(s,'exclusive',level);log(s,'Exclusive leads',`${count} deadline-bound offers. Securing is separate; only accept when staff can deploy immediately.`,'note');}
function recover(s,ids,oid){if(!ids.length||ids.length>4||new Set(ids).size!==ids.length)error('Select one to four returned operatives.');let members=ids.map(i=>merc(s,i));if(members.some(m=>m.status!=='Recovering'))error('Medical care requires returned Recovering personnel.');let o=checkAction(s,oid);checkTrained(o,'Medicine');spend(s,oid,'Establish Recovery Protocol',1,25*ids.length);let d=rollAdmin(s,oid,'Recovery Protocol','Medicine');let reduce=d>=2?d-1:0;for(const m of members){m.readyAt=Math.max(s.turn,m.readyAt-reduce);if(m.readyAt<=s.turn)m.status='Available';}log(s,'Medical care',`${names[d]}: remaining recovery reduced by ${reduce}, after actual return. Staff whose timer reaches zero are Available now.`,'good');}
function facilityQuote(type,repair=false){const f=V.facilities[type];if(!f||!['training_suite','infirmary'].includes(type))error('That facility is outside this demo.');return {turns:repair?1:f.turns,cost:(repair?round(f.cost*.2):f.cost)+100*(repair?1:f.turns),overhead:f.monthly};}
function project(s,type,oid,repairId=null){let active=s.projects.filter(p=>!p.done);if(active.length>=V.project_capacity[s.guildLevel])error('The guild has reached concurrent project capacity.');let current=repairId?s.facilities.find(f=>f.id===repairId):null;if(repairId&&(!current||current.condition!=='Damaged'))error('Choose a damaged facility to repair.');if(!repairId&&(s.facilities.length+active.filter(p=>!p.repairId).length>=2))error('The leased HQ has only two upgrade slots.');if(!repairId&&(s.facilities.some(f=>f.type===type)||active.some(p=>p.type===type&&!p.repairId)))error('This demo already has that installation or project.');let q=facilityQuote(type,!!repairId);spend(s,oid,(repairId?'Repair ':'Commission ')+type,1,q.cost);s.projects.push({id:id(s,'p'),type,due:s.turn+q.turns,repairId,done:false,cost:q.cost});log(s,'Project commissioned',`${type.replaceAll('_',' ')}: ${q.cost} funded, including ${100*q.turns} for a qualified external manager. Completes at Turn ${s.turn+q.turns}; ${q.overhead}/month afterward. Manager adds no officer actions.`,'good');}
function optimize(s,fid,oid){let f=s.facilities.find(x=>x.id===fid);if(!f)error('Choose an installed facility.');if(f.saving&&f.saving.turn===s.turn+1)error('That next bill already has an optimization attempt.');let o=checkAction(s,oid);checkTrained(o,'Crafting');spend(s,oid,'Optimize Infrastructure');let d=rollAdmin(s,oid,'Optimize Infrastructure','Crafting');f.saving={turn:s.turn+1,rate:[0,0,.1,.2][d]};log(s,'Maintenance plan',`${names[d]}: ${round(f.saving.rate*100)}% saving on this installation’s next overhead, rounded down. Rent, payroll and debt are unaffected.`,'good');}
function chooseLeaderFeat(s,mid,fid){const m=merc(s,mid);if(m.level<5||m.leaderFeat||!leaderFeats.some(f=>f.id===fid))error('This operative cannot make that feat choice.');m.leaderFeat=fid;log(s,m.name+' gains a Leader Feat',leaderFeats.find(f=>f.id===fid).name,'good');}
function availableGuildFeats(s){return guildFeats.filter(f=>s.guildLevel>=f.level&&!s.guildFeats.includes(f.id)&&(!f.requires||s.guildFeats.includes(f.requires)));}
function chooseGuildFeat(s,fid){if(s.phase!=='advancement'||s.featChoices<1||!availableGuildFeats(s).some(f=>f.id===fid))error('No eligible Guild Feat choice is pending.');s.guildFeats.push(fid);s.featChoices--;log(s,'Guild Feat earned',guildFeats.find(f=>f.id===fid).name,'good');}
function makeEvent(s){let n=(die(s.seed,'event',s.turn)-1)%3;if(n===0)return {type:'lead',title:'A contact calls in a favor',text:'Helix Transit has another ordinary delivery assignment. Take the lead now; securing and deployment wait for next turn’s Activity.'};if(n===1){let m=s.mercs.find(m=>!['Candidate','Inactive'].includes(m.status));return {type:'concern',member:m?.id,title:'The crew wants to be heard',text:(m?m.name:'A crew member')+' is frustrated by long hours and unclear expectations. Loyalty falls by 3. You can acknowledge it now; a funded Boost Morale action can follow next turn.'};}return {type:'community',title:'An invitation from the dockworkers',text:'A local association offers an introduction. Accept to improve its separate Relations by one step, up to Friendly; no cash or contract is automatic.'};}
function endActivity(s){if(s.phase!=='activity')error('Finish the current step first.');s.unusedHistory=s.unusedHistory||[];s.unusedHistory.push({turn:s.turn,shared:s.actions,officers:s.officers.map(o=>({name:o.name,unused:2-o.used}))});s.phase='event';s.event=makeEvent(s);if(s.event.type==='concern'&&s.event.member)changeLoyalty(s,merc(s,s.event.member),-3);log(s,'Guild Event: '+s.event.title,s.event.text,'event');}
function respondEvent(s,choice){if(s.phase!=='event')error('No event awaits a response.');if(choice==='accept'&&s.event.type==='lead'){addOffer(s,'cargo',1+Math.floor((s.turn-1)/6),{expires:s.turn+2});log(s,'Lead held for next turn','No free securing, deployment or cash. The contact leaves this offer open through next turn.');}if(choice==='accept'&&s.event.type==='community'){s.relations=Math.min(3,s.relations+1);log(s,'Introductions accepted','Dockworkers Relations improve; this is separate from public Reputation.','good');}if(s.event.type==='concern')log(s,'Concern acknowledged','There is no automatic Loyalty recovery. Consider an actual morale investment next Activity.');s.guildXP+=s.pendingGuildXP;s.pendingGuildXP=0;while(s.guildXP>=1000&&s.guildLevel<10){s.guildXP-=1000;s.guildLevel++;if([2,4,6,8,10].includes(s.guildLevel))s.featChoices++;log(s,'Guild reaches Level '+s.guildLevel,'Shared action and project-capacity changes start next turn. Choose an earned Guild Feat.','good');}s.phase='advancement';}
function bill(s,creditor,amount,type='rent'){if(amount<=0)return;let paid=Math.min(s.cash,amount);if(paid)money(s,-paid,creditor,type);if(paid<amount){s.arrears.push({id:id(s,'a'),creditor,amount:amount-paid,type,turn:s.turn});log(s,'Unpaid obligation',`${creditor}: ${amount-paid} remains owed. This demo records creditor-specific arrears; it does not simulate full eviction or collection.`, 'bad');}}
function payArrears(s){if(s.phase!=='activity')error('Pay arrears during routine Activity administration.');if(!s.arrears.length)error('No arrears are owed.');if(!s.cash)error('No treasury funds are available.');for(const b of s.arrears){let n=Math.min(b.amount,s.cash);b.amount-=n;if(n)money(s,-n,'Arrears: '+b.creditor,b.type);}s.arrears=s.arrears.filter(b=>b.amount>0);log(s,'Arrears payment','Only actual funded amounts were paid; this routine payment spent no Guild Action.','good');}
function advance(s){if(s.phase!=='advancement')error('Complete the event and advancement step.');s.turn++;s.phase='upkeep';s.upkeep={settled:false,choices:[],complete:false};s.actions=0;s.officers.forEach(o=>o.used=0);s.trustedUsed=false;s.pipelineUsed=false;s.event=null;s.lastRoll=null;for(const c of s.board)if(c.status==='Offer'&&c.expires<s.turn)c.status='Expired';for(const m of s.mercs){if(m.status==='Candidate'&&m.expires<s.turn)m.status='Expired';if(m.leaveAt&&m.leaveAt<=s.turn){if(m.loyalty===0)m.status='Inactive';delete m.leaveAt;}if(['Onboarding','Recovering'].includes(m.status)&&m.readyAt<=s.turn){m.status='Available';log(s,m.name+' is Available','Scheduled onboarding or recovery is complete.');}}if(!nextJob(s))settleUpkeep(s);}
function nextJob(s){return s.jobs.find(j=>j.due<=s.turn&&!j.settled&&j.rolls.length<3);}
function rollPhase(s){if(s.phase!=='upkeep'||s.upkeep.settled)error('There is no unsettled operation to roll.');let j=nextJob(s);if(!j)error('All due checks are already rolled.');let p=j.rolls.length;let persistent=j.rolls.filter(r=>r.degree===0).length*-2;let prev=p?j.rolls[p-1].degree:null;let next=prev===1?-1:prev===3?1:0;let check=j.quote.checks[p];let face=die(s.seed,'mission',j.departure,j.contract.id,p);let mod=check.modifier+persistent+next;let d=degree(face,mod,check.dc);j.rolls.push({...check,face,actualModifier:mod,forward:persistent+next,degree:d});log(s,j.contract.name+' · '+phases[p],`${check.leadName} (${check.skill}): ${face} +${mod} vs DC${check.dc}, ${names[d]}.`,'roll');if(!nextJob(s))settleUpkeep(s);return j.rolls[p];}
function settleUpkeep(s){if(s.upkeep.settled)return;if(nextJob(s))error('Resolve all due mission checks first.');let due=s.jobs.filter(j=>j.due<=s.turn&&!j.settled);for(const j of due){let card=V.contracts[j.contract.kind];let success=j.rolls.filter(r=>r.degree>=2).length>=card.required_successes&&(j.contract.essential===undefined||j.rolls[j.contract.essential].degree>=2);j.result={success};if(success)money(s,j.quote.payout,j.contract.name,'client');}
 for(const j of due){let card=V.contracts[j.contract.kind],success=j.result.success;let phaseRecovery=j.rolls.some(r=>r.degree===0)?1:0;let passive=j.quote.leaderFeat==='hardcase'||s.facilities.some(f=>f.type==='infirmary'&&f.condition==='Operational')?1:0;let recovery=Math.max(card.mandatory_recovery,Math.max(0,phaseRecovery-passive));j.result.recovery=recovery;j.settled=true;let eligible=new Set();for(const r of j.rolls)if(r.degree>=2){eligible.add(r.lead);for(const h of r.supporters)if(h.marginal>0&&degree(r.face,r.actualModifier-h.marginal,r.dc)<r.degree)eligible.add(h.id);}for(const i of j.ids){let m=merc(s,i);xp(s,m,card.participation_xp+(success?card.completion_xp:0));m.status=recovery?'Recovering':'Available';m.readyAt=s.turn+recovery;if(success&&j.quote.leaderFeat==='advocate')changeLoyalty(s,m,1);}if(success){s.metrics.completed++;s.pendingGuildXP+=card.guild_xp;if(j.leader)xp(s,merc(s,j.leader),50);if(!s.contacts.includes(j.contract.client))s.contacts.push(j.contract.client);bill(s,'Successful wages: '+j.contract.name,j.quote.pay,'wages');s.upkeep.choices.push({id:id(s,'u'),type:'mvp',job:j.id,eligible:[...eligible]});}else{s.metrics.failed++;s.upkeep.choices.push({id:id(s,'u'),type:'failedPay',job:j.id});}changeRep(s,success?card.reputation_success:card.reputation_failure);offer(s,j.contract.id).status=success?'Completed':'Failed';log(s,success?'Contract completed':'Contract failed',`${j.contract.name}: ${success?j.quote.payout+' client credits, completion XP and Guild XP.':'zero client cash; participation XP only.'} Recovery ${recovery}; Reputation ${success?'+'+card.reputation_success:card.reputation_failure}.`,success?'good':'bad');}
 for(const c of s.board)if(c.status==='Accepted'&&c.deployBy<s.turn){c.status='Expired';if(c.kind==='exclusive'){s.metrics.failed++;changeRep(s,V.contracts.exclusive.reputation_failure);log(s,'Exclusive deadline breached',`${c.name}: no meaningful attempt, no XP or payout; Reputation −4.`, 'bad');}else log(s,'Ordinary contract expired',c.name+': uncompleted, no rewards and no Reputation penalty.');}
 for(const c of s.cohorts)if(c.active&&c.due<=s.turn&&!c.waiting){let award=Math.floor(150*(1+Math.min(.1*(c.block-1),.5))+1e-8);c.ids.forEach(i=>xp(s,merc(s,i),award));c.waiting=true;s.metrics.trainingBlocks++;s.upkeep.choices.push({id:id(s,'u'),type:'training',cohort:c.id});log(s,'Training block '+c.block+' completed',`${award} XP each. Stop and release the cohort, or fund another consecutive block without a new action.`, 'good');}
 for(const p of s.projects)if(!p.done&&p.due<=s.turn){p.done=true;if(p.repairId){s.facilities.find(f=>f.id===p.repairId).condition='Operational';log(s,'Facility repaired','Its original benefits return; repairs award no Guild XP.','good');}else{s.facilities.push({id:id(s,'f'),type:p.type,condition:'Operational',activeSince:s.turn});s.pendingGuildXP+=200;log(s,'Facility comes online',p.type.replaceAll('_',' ')+': 200 once-only development Guild XP. Overhead starts accruing now, payable next boundary.','good');}}
 bill(s,'HQ lease and ordinary overhead',150,'rent');for(const f of s.facilities)if(f.activeSince<s.turn){let amount=V.facilities[f.type].monthly;if(f.saving?.turn===s.turn)amount-=Math.floor(amount*f.saving.rate);bill(s,f.type.replaceAll('_',' ')+' overhead',amount,'facility');}
 s.upkeep.settled=true;log(s,'Monthly bills settled','All due client receipts arrived before automatic successful payroll, HQ rent and installed-facility overhead. Failed wages and training continuation are your choices.');}
function choice(s,cid,value){if(s.phase!=='upkeep'||!s.upkeep.settled)error('Resolve due work first.');let c=s.upkeep.choices.find(x=>x.id===cid);if(!c)error('That choice is already settled.');if(c.type==='failedPay'){let j=s.jobs.find(x=>x.id===c.job);if(!['full','half','none'].includes(value))error('Choose full, half or no failed-job wages.');let amount=round(j.quote.pay*({full:1,half:.5,none:0}[value]));checkFunds(s,amount);if(amount)money(s,-amount,'Failed wages: '+j.contract.name,'failedWages');j.failedPay=value;j.ids.forEach(i=>changeLoyalty(s,merc(s,i),V.failed_pay_loyalty[value]));log(s,'Failed-job pay chosen',`${value}: ${amount} credits actually paid; Loyalty ${V.failed_pay_loyalty[value]>=0?'+':''}${V.failed_pay_loyalty[value]}. Waived remainder creates no default debt, and Reputation is unchanged.`,'note');}else if(c.type==='mvp'){if(value!=='none'&&!c.eligible.includes(value))error('Choose a materially contributing eligible operative, or no MVP.');let j=s.jobs.find(x=>x.id===c.job);if(value!=='none'){xp(s,merc(s,value),50);j.mvp=value;log(s,'MVP recognized',merc(s,value).name+' gains 50 XP for documented contribution.','good');}}else if(c.type==='training'){let cohort=s.cohorts.find(x=>x.id===c.cohort);if(value==='continue'){let cost=trainingCost(s,cohort.ids);checkFunds(s,cost);money(s,-cost,'Consecutive training block','training');cohort.block++;cohort.due=s.turn+1;cohort.waiting=false;log(s,'Training continues',`Block ${cohort.block} funded for ${cost}. No new action; cohort remains Training. Next block bonus is not retroactive.`,'good');}else if(value==='stop'){cohort.active=false;cohort.waiting=false;cohort.ids.forEach(i=>merc(s,i).status='Available');log(s,'Training ends','Crew are Available; the consecutive streak has ended.');}else error('Choose continue or stop.');}s.upkeep.choices=s.upkeep.choices.filter(x=>x.id!==cid);}
function finishUpkeep(s){if(s.phase!=='upkeep'||!s.upkeep.settled||s.upkeep.choices.length)error('Complete all Upkeep decisions first.');s.actions=V.guild_actions[s.guildLevel];s.phase='activity';s.upkeep.complete=true;if(s.guildFeats.includes('standing'))addOffer(s,'escort',1+Math.floor((s.turn-1)/6),{standing:true});log(s,'Budget resets',`${s.actions} shared actions; each officer may execute two. Routine deployment needs no action. Guild XP from this Upkeep settles at end of this turn.`,'good');}
function summary(s){let completed=s.jobs.filter(j=>j.settled);return ['# Contract Operations browser playtest','Rules: 0.3.1 · Seed: '+s.seed+' · Acquisition: '+(s.freeAcquisition?'free':'one action'),'Guild Turn '+s.turn+' · Phase '+s.phase,'Treasury: '+s.cash+' · Arrears: '+s.arrears.reduce((a,x)=>a+x.amount,0),'Guild Level: '+s.guildLevel+' · Guild XP: '+s.guildXP+' + '+s.pendingGuildXP+' pending','Contracts completed/failed: '+s.metrics.completed+'/'+s.metrics.failed,'Roster: '+s.mercs.filter(m=>!['Candidate','Expired'].includes(m.status)).map(m=>m.name+' L'+m.level+' '+m.status+' XP'+m.xp+' Loyalty'+m.loyalty).join('; '),'','## Feedback',s.feedback||'(No notes yet)','',...s.log.slice().reverse().map(l=>'T'+l.turn+' · '+l.title+' — '+l.text)].join('\n');}
const api={V,names,phases,templates,people,leaderFeats,guildFeats,clamp,round,wage,rank,support,skill,degree,die,fresh,merc,offer,officer,available,administrativeDC,quote,secure,deploy,network,hire,train,trainingCost,trainingCapacity,promote,morale,recon,broker,recover,project,facilityQuote,optimize,chooseLeaderFeat,availableGuildFeats,chooseGuildFeat,endActivity,respondEvent,advance,nextJob,rollPhase,choice,finishUpkeep,payArrears,summary};
root.GuildGame=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
